def load() -> pd.DataFrame:
    import os
    base = './amber/user-resources/workflow-results/operator-port-result'
    results = []
    try:
        for f in os.listdir(base):
            full = os.path.join(base, f)
            try:
                size = os.path.getsize(full)
                results.append({'path': full, 'size': size})
            except:
                pass
    except Exception as e:
        return pd.DataFrame({'error': [str(e)]})
    df = pd.DataFrame(results)
    if df.empty:
        return pd.DataFrame({'msg': ['no results']})
    return df.sort_values('size', ascending=False).head(30)

def load() -> pd.DataFrame:
    import os, pickle, json
    # The search_large_cached showed all files are 4096 bytes (directory entries)
    # Let's look for actual large files in amber results
    base = './amber/user-resources/workflow-results/operator-port-result'
    results = []
    for f in os.listdir(base):
        full = os.path.join(base, f)
        if os.path.isdir(full):
            # It's a directory - check files inside
            try:
                inner = os.listdir(full)
                for ff in inner:
                    fpath = os.path.join(full, ff)
                    sz = os.path.getsize(fpath)
                    results.append({'path': fpath, 'size': sz, 'name': ff})
            except:
                pass
    df = pd.DataFrame(results)
    if len(df) > 0:
        df = df.sort_values('size', ascending=False).head(30)
    return df
